"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6834],{46834:a=>{a.exports=JSON.parse('{"slug":"yandex-data-centry-ataki-sboi-oblako","locale":"es","title":"Ataques a 3 centros de datos de Yandex en 4 d\xedas interrumpen decenas de servicios","description":"Entre el 8 y el 11 de octubre de 2026 se atacan 3 centros de Yandex de hasta 115 MW conjuntos. Qu\xe9 falla y por qu\xe9 ser\xe1 caro recuperar la capacidad.","blocks":[{"id":"b001","kind":"paragraph","text":"El 8 de octubre de 2026, un ataque con dron e incendio detuvo el centro de Yandex en Sasovo, de unos 12 MW. El 9 fue da\xf1ado el de Kaluga, de 63 MW y m\xe1s de 3800 bastidores. El 11 se detuvo por completo Vladimir, de unos 40 MW. Suman hasta 115 MW, cerca del 6% de la capacidad rusa total de unos 1,8 GW. En Vladimir no hubo heridos. Yandex no revela da\xf1os ni plazos de reparaci\xf3n."},{"id":"b002","kind":"paragraph","text":"Fallaron Yandex Go, Pay, correo, mapas y comida. Tampoco se ped\xedan taxis en Kazajist\xe1n, Bielorrusia, Armenia y Serbia. Se interrumpieron servicios ajenos alojados en Yandex Cloud, como Cian, promotoras y Astral. El 11 de octubre, Yandex anunci\xf3 una recuperaci\xf3n gradual, pero el 12, Dmitry Pirogov dijo que a\xfan no pod\xeda fijarse la restauraci\xf3n completa de Yandex Pay."},{"id":"b003","kind":"paragraph","text":"La nube alquila servidores: pagas capacidad sin construir el centro. Es c\xf3modo mientras funciona. Como una familia con todo el dinero en una tarjeta: bloqueada, no puede pagar. La protecci\xf3n es una copia en otra instalaci\xf3n, llamada redundancia. Cuesta 2 conjuntos de capacidad en vez de 1 y muchos ahorran ah\xed. Yandex Cloud tiene zonas separadas, pero fallaron 2 de 4, Vladimir y Sasovo. La empresa calific\xf3 las restantes de inestables y recomend\xf3 alternativas; acord\xf3 con VK Cloud, Selectel y K2Cloud alojar r\xe1pidamente datos y servicios de clientes."},{"id":"b004","kind":"paragraph","text":"Restaurar ser\xe1 caro. Servidores y aceleradores escasean por la demanda de IA. El suministro tarda de 2–3 a 6 meses. Eldar Murtazin afirma que el equipo ruso subi\xf3 un 10–15% en d\xedas. Nikita Tsaplin se\xf1ala nuevas protecciones de centros que probablemente pagar\xe1 el cliente. Sergey Kudryashov estima ingresos de Yandex Cloud cercanos a 30 mil millones de rublos, un 2–4% del grupo. Es peque\xf1o para Yandex, pero sus servicios principales usan esos mismos centros."},{"id":"b005","kind":"paragraph","text":"Para el usuario signific\xf3 taxis o pagos sin funcionar. El canal indirecto es m\xe1s largo: si equipo y protecci\xf3n encarecen la nube, las empresas trasladar\xe1n parte a sus servicios. Nadie cuantifica todav\xeda cu\xe1nto."},{"id":"b006","kind":"paragraph","text":"Para la empresa la elecci\xf3n es inc\xf3moda: una segunda instalaci\xf3n o migrar cuesta ahora, con equipos escasos. Depender de un proveedor es m\xe1s barato, pero otro fallo detendr\xeda ventas. No se sabe cu\xe1ndo volver\xe1 la capacidad anterior de Yandex."},{"id":"b007","kind":"heading","text":"\xbfQu\xe9 centros se atacaron en octubre de 2026?"},{"id":"b008","kind":"paragraph","text":"El 8 de octubre se detuvo Sasovo, de unos 12 MW; el 9 se da\xf1\xf3 Kaluga, de 63 MW; el 11 se par\xf3 Vladimir, de unos 40 MW."},{"id":"b009","kind":"heading","text":"\xbfQu\xe9 servicios dejaron de funcionar?"},{"id":"b010","kind":"paragraph","text":"Yandex Go, Pay, correo, mapas y comida, junto con clientes de nube como Cian y Astral. Tambi\xe9n hubo problemas para pedir taxis en Kazajist\xe1n, Bielorrusia, Armenia y Serbia."},{"id":"b011","kind":"heading","text":"\xbfCu\xe1ndo se restaurar\xe1n?"},{"id":"b012","kind":"paragraph","text":"No hay fechas precisas. Vuelven gradualmente, pero el equipo de sustituci\xf3n tarda de 2 a 6 meses. El 12 de octubre, Yandex Pay a\xfan no pod\xeda indicar su plazo de recuperaci\xf3n."}],"sources":[{"label":"Un ataque a Yandex provoca una cadena de fallos: afectados","url":"https://thebell.io/ataka-na-data-tsentr-yandeksa-vyzvala-tsepnuyu-reaktsiyu-sboev-kto-postradal"},{"label":"Los drones interrumpen Yandex y amenazan con encarecer la nube","url":"https://www.kommersant.ru/doc/9024163"},{"label":"Tercer centro de Yandex atacado por drones en una semana","url":"https://ru.themoscowtimes.com/2026/10/11/droni-atakovali-tretii-data-tsentr-yandeksa-zanedelyu-a208309"},{"label":"Detalles del ataque al centro de Vladimir","url":"https://www.fontanka.ru/2026/10/11/76693363/"},{"label":"Consecuencias de los ataques a Yandex seg\xfan expertos","url":"https://www.fontanka.ru/2026/10/11/76693413/"},{"label":"Otro fallo de Yandex: Vladimir detenido y ru-central1-a inaccesible","url":"https://www.comss.ru/page.php?id=22366"},{"label":"Yandex Pay no puede fijar su recuperaci\xf3n","url":"https://vz.ru/news/2026/10/12/1461835.html"}],"sourceBodySha256":"90f104461afebdbd416e2a7cbc14c93eb9a1629170e459918558786e22c1b0b1"}')}}]);